        "операционная система Windows 11). База данных предварительно заполнена "
        "сгенерированным тестовым набором: 2 000 клиентов, 4 500 абонементов, "
        "12 000 занятий за два года и 75 000 записей о посещениях. Замеры "
        "выполнены утилитой curl с измерением полного времени запроса "
