        "программный пакет locust. Сценарий имитирует одновременную работу "
        "10 пользователей в течение 5 минут, выполняющих типичный набор "
        "операций: получение расписания, поиск клиента, фиксация посещения. "
        "Под указанной нагрузкой сервер обработал в среднем 320 запросов "
